export function StatusBadge({
  label = "{{label}}",
  status = "{{status}}",
  showDot = {{showDot}},
  pulsing = {{pulsing}},
}) {
  const palette = {
    online: { color: "#17532F", background: "#A8E6C1", borderColor: "#17532F33" },
    away: { color: "#4A2E00", background: "#E8A020", borderColor: "#4A2E0033" },
    busy: { color: "#FAF7F2", background: "#B3261E", borderColor: "#B3261E" },
    offline: { color: "#24143080", background: "#24143014", borderColor: "#24143022" },
  }[status] ?? {};
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontWeight: 600, fontSize: 12.5,
      padding: "4px 10px", borderRadius: 999, boxSizing: "border-box", border: "1px solid", ...palette }}>
      {showDot && (
        <span aria-hidden="true" style={{ width: 7, height: 7, borderRadius: "50%", background: "currentColor",
          flexShrink: 0, animation: pulsing ? "status-badge-react-pulse 1.4s ease-in-out infinite" : "none" }} />
      )}
      {label}
      <style>{`@keyframes status-badge-react-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .4; } }`}</style>
    </span>
  );
}
